fixes.js:
var strip = document.querySelector('.date-strip');
if (!strip || strip.dataset.auditLabelled) return;
strip.dataset.auditLabelled = '1';
strip.querySelectorAll('.day').forEach(function (chip) {
  var state = chip.classList.contains('is-full') ? 'full' : chip.classList.contains('is-closed') ? 'closed' : 'open';
  var num = chip.textContent.trim();
  var n = document.createElement('span');
  n.className = 'day-num';
  n.textContent = num;
  var s = document.createElement('span');
  s.className = 'day-status';
  s.textContent = state === 'full' ? 'Sold out' : state === 'closed' ? 'Closed' : 'Open';
  chip.textContent = '';
  chip.append(n, s);
  if (state !== 'closed') {
    chip.setAttribute('aria-label', (chip.dataset.label || num) + (state === 'full' ? ', sold out (waitlist only)' : ', seats available'));
  }
});
var legend = document.querySelector('.legend');
if (legend) {
  legend.innerHTML = '<span><span class="sw open"></span>Open: seats available</span>' +
    '<span><span class="sw full"></span>Sold out: waitlist only</span>';
}
var strip = document.querySelector('.date-strip');
if (strip) {
  var cols = Array.prototype.slice.call(strip.querySelectorAll('.day-col'));
  var idx = cols.findIndex(function (c) { return c.querySelector('[data-date]'); });
  if (idx >= 0) {
    var d = new Date(cols[idx].querySelector('[data-date]').dataset.date + 'T12:00:00');
    var weekday = (d.getDay() + 6) % 7; // Monday = 0
    cols[0].style.gridColumnStart = String((((weekday - idx) % 7) + 7) % 7 + 1);
  }
}

