var form = document.getElementById('booking-form');
var strip = document.querySelector('.date-strip');
if (!form || !strip || strip.dataset.auditKeyboard) return;
strip.dataset.auditKeyboard = '1';
strip.setAttribute('role', 'group');
strip.setAttribute('aria-label', 'Choose a date');
function chipsNow() { return Array.prototype.slice.call(strip.querySelectorAll('button.day[data-date]')); }
function select(btn) {
  if (typeof window.pickDate === 'function') {
    window.pickDate(btn);
  } else { // static copy of the page (original scripts removed): do the same updates here
    chipsNow().forEach(function (c) { c.classList.toggle('is-selected', c === btn); });
    var input = form.elements.namedItem('date');
    if (input) input.value = btn.dataset.date;
    var label = document.getElementById('sum-date');
    if (label) { label.textContent = btn.dataset.label || btn.dataset.date; label.classList.remove('is-empty'); }
    var err = document.getElementById('reserve-error');
    if (err) err.hidden = true;
  }
  chipsNow().forEach(function (c) {
    c.setAttribute('aria-pressed', c === btn ? 'true' : 'false');
    c.tabIndex = c === btn ? 0 : -1;
  });
}
// 1. Date chips: <div onclick> -> <button type="button"> (focusable, Enter/Space work natively)
strip.querySelectorAll('div.day[data-date]').forEach(function (div) {
  var b = document.createElement('button');
  b.type = 'button';
  for (var i = 0; i < div.attributes.length; i++) {
    var at = div.attributes[i];
    if (at.name !== 'onclick') b.setAttribute(at.name, at.value);
  }
  b.innerHTML = div.innerHTML;
  b.setAttribute('aria-pressed', div.classList.contains('is-selected') ? 'true' : 'false');
  b.addEventListener('click', function () { select(b); });
  div.replaceWith(b);
});
// 2. One Tab stop for the date group (the selected date, else the first open one); arrow keys move between dates
var chips = chipsNow();
var start = chips.filter(function (c) { return c.classList.contains('is-selected'); })[0] ||
  chips.filter(function (c) { return c.classList.contains('is-open'); })[0] || chips[0];
chips.forEach(function (c) { c.tabIndex = c === start ? 0 : -1; });
strip.addEventListener('keydown', function (e) {
  var list = chipsNow();
  var i = list.indexOf(document.activeElement);
  if (i < 0) return;
  var days = { ArrowRight: 1, ArrowLeft: -1, ArrowDown: 7, ArrowUp: -7 }[e.key];
  var j = e.key === 'Home' ? 0 : e.key === 'End' ? list.length - 1 : -1;
  if (days !== undefined) {
    var target = new Date(list[i].dataset.date + 'T12:00:00').getTime() + days * 864e5;
    var dir = days > 0 ? 1 : -1;
    for (var k = i + dir; k >= 0 && k < list.length; k += dir) {
      var t = new Date(list[k].dataset.date + 'T12:00:00').getTime();
      if (dir > 0 ? t >= target : t <= target) { j = k; break; }
    }
    if (j < 0) j = dir > 0 ? list.length - 1 : 0;
  }
  if (j < 0) return;
  e.preventDefault();
  list[i].tabIndex = -1;
  list[j].tabIndex = 0;
  list[j].focus();
});
// 3. Reserve: <div onclick> -> real submit button of the booking form
var cta = document.querySelector('div.reserve-cta');
if (cta) {
  var r = document.createElement('button');
  r.type = 'submit';
  r.className = cta.className;
  r.innerHTML = cta.innerHTML;
  cta.replaceWith(r);
}

